package tag

// TagInfo contains metadata about a DICOM tag
type TagInfo struct {
	Tag     uint32 // The tag as uint32
	VR      string // Value Representation
	VM      string // Value Multiplicity
	Name    string // Human-readable name
	Retired bool   // Is this tag retired?
	Keyword string // Programmatic identifier
}

// RepeaterTag represents a repeating tag pattern (e.g., "60xx3000")
type RepeaterTag struct {
	Mask    string // Pattern like "60xx3000"
	VR      string // Value Representation
	VM      string // Value Multiplicity
	Name    string // Human-readable name
	Retired bool   // Is this tag retired?
	Keyword string // Programmatic identifier
}

